package com.aistock.prediction.modelcatalog;
import com.aistock.common.BusinessException;import com.aistock.prediction.analysis.*;import com.aistock.prediction.marketuse.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@Tag("mysql") class AnalysisMarketUseMysqlTest {
 final ObjectMapper m=new ObjectMapper();final Instant now=Instant.parse("2026-10-07T07:00:00Z");
 AnalysisInput input(){return new AnalysisInput(UUID.randomUUID(),"SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),UUID.randomUUID());}
 MarketUseClient.Receipt receipt(AnalysisInput in){return new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(in.marketVersionId().toString()));}
 @Test void registrationIsPersistedBeforeNetworkAndProofUsesActualIrreversibleTerminal(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var in=input();var user=UUID.randomUUID();repo.begin(user,in,now);var client=mock(MarketUseClient.class);var owner=new MarketUseOwnerService(db.jdbc,m,repo,client,Clock.fixed(now,ZoneOffset.UTC),true);var receipt=receipt(in);
  when(client.register(any())).thenAnswer(call->{assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());assertEquals(1,db.jdbc.queryForObject("select count(*) from stock_analysis_market_use where registration_started=true",Integer.class));return receipt;});
  try(var scope=owner.acquire(in.operationId(),1)){assertEquals(receipt.bundleId(),MarketUseContext.headers().get("X-Market-Use-Bundle"));assertEquals(in.operationId().toString(),MarketUseContext.headers().get("X-Market-Use-Operation"));assertThrows(BusinessException.class,()->owner.proof("STOCK_ANALYSIS",in.operationId(),"1"));}
  assertTrue(MarketUseContext.headers().isEmpty());repo.complete(in.operationId(),1,null,"TEST_FAILURE",now.plusSeconds(1));var proof=owner.proof("STOCK_ANALYSIS",in.operationId(),"1");assertEquals("FAILED",proof.path("state").asText());assertEquals(in.marketVersionId().toString(),proof.path("versionIds").get(0).asText());assertEquals(proof,new MarketUseOwnerService(db.jdbc,m,repo,client,Clock.fixed(now,ZoneOffset.UTC),false).proof("STOCK_ANALYSIS",in.operationId(),"1"));assertFalse(proof.has("userId"));assertFalse(proof.has("question"));var keys=new HashSet<String>();proof.fieldNames().forEachRemaining(keys::add);assertEquals(Set.of("owner","purpose","ownerOperationId","generation","state","terminalAt","fencingRevision","resultIdentity","versionIds"),keys);assertThrows(BusinessException.class,()->owner.proof("STOCK_ANALYSIS",in.operationId(),"2"));
 }
 @Test void unknownRegistrationRecoversOriginalRequestWithoutAnotherPost(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var in=input();repo.begin(UUID.randomUUID(),in,now);var client=mock(MarketUseClient.class);var owner=new MarketUseOwnerService(db.jdbc,m,repo,client,Clock.fixed(now,ZoneOffset.UTC),true);when(client.register(any())).thenThrow(new BusinessException("MARKET_USE_UNAVAILABLE","fixture",org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE));assertThrows(BusinessException.class,()->owner.acquire(in.operationId(),1));var request=org.mockito.ArgumentCaptor.forClass(MarketUseClient.Request.class);verify(client).register(request.capture());repo.complete(in.operationId(),1,null,"MARKET_USE_UNAVAILABLE",now.plusSeconds(1));when(client.find(request.getValue())).thenReturn(Optional.of(receipt(in)));owner.recoverOne(in.operationId(),1);verify(client,times(1)).register(any());verify(client).find(request.getValue());assertDoesNotThrow(()->owner.proof("STOCK_ANALYSIS",in.operationId(),"1"));}
 @Test void notificationFailureDoesNotChangeTerminalAndCanBeRecovered(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var in=input();var user=UUID.randomUUID();repo.begin(user,in,now);var client=mock(MarketUseClient.class);var owner=new MarketUseOwnerService(db.jdbc,m,repo,client,Clock.fixed(now,ZoneOffset.UTC),true);var r=receipt(in);when(client.register(any())).thenReturn(r);try(var scope=owner.acquire(in.operationId(),1)){}repo.complete(in.operationId(),1,null,"TEST_FAILURE",now.plusSeconds(1));when(client.complete(any(),any())).thenThrow(new BusinessException("MARKET_USE_UNAVAILABLE","fixture",org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE));owner.notifyCompleted(in.operationId(),1);assertEquals("FAILED",repo.replay(user,in,now).path("state").asText());assertFalse(db.jdbc.queryForObject("select completion_acked from stock_analysis_market_use",Boolean.class));doReturn(new MarketUseClient.Receipt(r.bundleId(),"RELEASED",r.versionIds())).when(client).complete(any(),any());owner.recoverOne(in.operationId(),1);assertTrue(db.jdbc.queryForObject("select completion_acked from stock_analysis_market_use",Boolean.class));}
 @Test void disabledOwnerHasNoNetworkOrUseRecords(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var client=mock(MarketUseClient.class);var owner=new MarketUseOwnerService(db.jdbc,m,repo,client,Clock.systemUTC(),false);try(var scope=owner.acquire(UUID.randomUUID(),1)){assertTrue(MarketUseContext.headers().isEmpty());}owner.notifyCompleted(UUID.randomUUID(),1);owner.recoverBatch();verifyNoInteractions(client);assertEquals(0,db.jdbc.queryForObject("select count(*) from stock_analysis_market_use",Integer.class));}

 @Test void enabledAnalysisBindsBeforeEvidenceAndNotifiesOnlyAfterResultCommit(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var in=input();var user=UUID.randomUUID();var c=mock(MarketUseClient.class);var owner=new MarketUseOwnerService(db.jdbc,m,repo,c,Clock.fixed(now,ZoneOffset.UTC),true);var receipt=receipt(in);when(c.register(any())).thenReturn(receipt);when(c.complete(any(),any())).thenAnswer(call->{assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());assertEquals(1,db.jdbc.queryForObject("select count(*) from stock_analysis_result",Integer.class));assertEquals("SUCCEEDED",db.jdbc.queryForObject("select state from stock_analysis_operation",String.class));return new MarketUseClient.Receipt(receipt.bundleId(),"RELEASED",receipt.versionIds());});var ai=new AnalysisHttpTest.Client();AnalysisMarketClient market=(id,from,to,version)->{assertEquals(receipt.bundleId(),MarketUseContext.headers().get("X-Market-Use-Bundle"));assertEquals(1,db.jdbc.queryForObject("select count(*) from stock_analysis_market_use where bundle_id is not null",Integer.class));return ai.evidence(id,from,to,version,m);};var svc=new AnalysisService(repo,market,ai,m,Clock.fixed(now,ZoneOffset.UTC),null,owner);var result=svc.generate(user,in);assertEquals("SUCCEEDED",result.path("state").asText());assertTrue(db.jdbc.queryForObject("select completion_acked from stock_analysis_market_use",Boolean.class));assertEquals(1,ai.calls);assertEquals(result,svc.generate(user,in));assertEquals(1,ai.calls);verify(c,times(1)).register(any());assertTrue(MarketUseContext.headers().isEmpty());assertEquals(result.path("analysisId").asText(),owner.proof("STOCK_ANALYSIS",in.operationId(),"1").path("resultIdentity").asText());}
 @Test void permissionOrReadinessRefusalNeverFetchesEvidenceOrCallsModel(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var in=input();var user=UUID.randomUUID();var c=mock(MarketUseClient.class);doThrow(MarketUseClient.notReady()).when(c).requireReady();var owner=new MarketUseOwnerService(db.jdbc,m,repo,c,Clock.fixed(now,ZoneOffset.UTC),true);var ai=new AnalysisHttpTest.Client();var market=mock(AnalysisMarketClient.class);var svc=new AnalysisService(repo,market,ai,m,Clock.fixed(now,ZoneOffset.UTC),null,owner);assertThrows(BusinessException.class,()->svc.generate(user,in));assertEquals("FAILED",repo.replay(user,in,now).path("state").asText());verifyNoInteractions(market);verify(c,never()).register(any());assertEquals(0,ai.calls);assertFalse(db.jdbc.queryForObject("select registration_started from stock_analysis_market_use",Boolean.class));assertTrue(MarketUseContext.headers().isEmpty());}
 @Test void missingRecoveryReceiptRemainsUnknownAndDoesNotPostAgain(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var in=input();repo.begin(UUID.randomUUID(),in,now);var c=mock(MarketUseClient.class);when(c.register(any())).thenThrow(MarketUseClient.unavailable());var owner=new MarketUseOwnerService(db.jdbc,m,repo,c,Clock.fixed(now,ZoneOffset.UTC),true);assertThrows(BusinessException.class,()->owner.acquire(in.operationId(),1));when(c.find(any())).thenReturn(Optional.empty());var restarted=new MarketUseOwnerService(db.jdbc,m,repo,c,Clock.fixed(now,ZoneOffset.UTC),true);restarted.recoverOne(in.operationId(),1);verify(c,times(1)).register(any());verify(c,never()).complete(any(),any());assertNull(db.jdbc.queryForObject("select bundle_id from stock_analysis_market_use",String.class));assertFalse(db.jdbc.queryForObject("select completion_acked from stock_analysis_market_use",Boolean.class));}

 @Test void recoveryIsBoundedAndUnknownRowsDoNotStarveLaterRows(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var c=mock(MarketUseClient.class);when(c.register(any())).thenThrow(MarketUseClient.unavailable());when(c.find(any())).thenReturn(Optional.empty());var owner=new MarketUseOwnerService(db.jdbc,m,repo,c,Clock.fixed(now,ZoneOffset.UTC),true);for(int i=0;i<27;i++){var in=input();repo.begin(UUID.randomUUID(),in,now);assertThrows(BusinessException.class,()->owner.acquire(in.operationId(),1));}clearInvocations(c);owner.recoverBatch();verify(c,times(25)).find(any());var captured=org.mockito.ArgumentCaptor.forClass(MarketUseClient.Request.class);owner.recoverBatch();verify(c,times(50)).find(captured.capture());assertEquals(27,captured.getAllValues().stream().map(MarketUseClient.Request::requestId).distinct().count());verify(c,never()).register(any());verify(c,never()).complete(any(),any());}

 @Test void malformedOldReceiptsCannotStarveHealthyPendingRegistrations(){var db=new ModelDatabaseFixture();var repo=new AnalysisRepository(db.jdbc,m);var c=mock(MarketUseClient.class);when(c.register(any())).thenThrow(MarketUseClient.unavailable());when(c.find(any())).thenReturn(Optional.empty());var owner=new MarketUseOwnerService(db.jdbc,m,repo,c,Clock.fixed(now,ZoneOffset.UTC),true);for(int i=0;i<26;i++){var in=input();repo.begin(UUID.randomUUID(),in,now);assertThrows(BusinessException.class,()->owner.acquire(in.operationId(),1));}db.jdbc.update("update stock_analysis_market_use set bundle_id=operation_id,receipt_json=json_object('bundleId',operation_id,'state','BROKEN','versionIds',json_array(raw_version_id)) order by last_checked_at,operation_id limit 25");clearInvocations(c);owner.recoverBatch();owner.recoverBatch();verify(c,times(1)).find(any());verify(c,never()).register(any());verify(c,never()).complete(any(),any());assertEquals(0,db.jdbc.queryForObject("select count(*) from stock_analysis_market_use where completion_acked=true",Integer.class));}
}
